    "pp-ocr-2020": Object.freeze({ kind: "Primary research paper", shortTitle: "PP-OCR", note: "Describes a practical OCR system combining text detection, direction classification, and recognition. It does not guarantee reliable recovery of every scan quality, layout, or table relationship." }),
